const id = ($json.body && $json.body.post_id) || '';
if (!id) throw new Error('post_id fehlt im Webhook-Body');
return [{ json: { post_id: id } }];

const post = $json;
const plattformen = post.plattformen || [];
if (plattformen.length === 0) {
  throw new Error('Post ' + post.id + ' hat keine Plattform ausgewaehlt');
}
const erstesBild = (post.medien && post.medien[0])
  ? `https://pb.ascensus.fit/api/files/social_posts/${post.id}/${post.medien[0]}`
  : '';
return plattformen.map(p => ({
  json: {
    post_id: post.id,
    text: post.text || '',
    bild_url: erstesBild,
    plattform: p
  }
}));

const hatBild = !!$json.bild_url;
const PAGE_ID = 'FACEBOOK_PAGE_ID';
return [{
  json: {
    post_id: $json.post_id,
    plattform: 'facebook',
    url: hatBild
      ? `https://graph.facebook.com/v19.0/${PAGE_ID}/photos`
      : `https://graph.facebook.com/v19.0/${PAGE_ID}/feed`,
    body: hatBild
      ? { url: $json.bild_url, caption: $json.text, published: true }
      : { message: $json.text }
  }
}];

const r = $json;
const post_id = $('Facebook: Request vorbereiten').item.json.post_id;
if (r.error) {
  return [{ json: { post_id, plattform: 'facebook', ok: false, fehler: r.error.message || JSON.stringify(r.error) } }];
}
return [{ json: { post_id, plattform: 'facebook', ok: true, url: r.post_id ? ('https://facebook.com/' + r.post_id) : null } }];

const post_id = $('Instagram: Vorbereiten').item.json.post_id;
if ($json.error) {
  return [{ json: { post_id, plattform: 'instagram', ok: false, fehler: $json.error.message || JSON.stringify($json.error), abbrechen: true } }];
}
return [{ json: { post_id, plattform: 'instagram', creation_id: $json.id, abbrechen: false } }];

const vorher = $('Instagram: Container-ID lesen').item.json;
if (vorher.abbrechen) {
  return [{ json: { post_id: vorher.post_id, plattform: 'instagram', ok: false, fehler: vorher.fehler } }];
}
if ($json.error) {
  return [{ json: { post_id: vorher.post_id, plattform: 'instagram', ok: false, fehler: $json.error.message || JSON.stringify($json.error) } }];
}
return [{ json: { post_id: vorher.post_id, plattform: 'instagram', ok: true, url: null } }];

const post_id = $('Plattformen aufteilen').first().json.post_id;
if ($json.error) {
  return [{ json: { post_id: $json.__post_id || post_id, plattform: 'linkedin', ok: false, fehler: 'LinkedIn-API nicht verfuegbar oder Berechtigung fehlt - Beitrag manuell posten (Text-kopieren-Button nutzen).' } }];
}
return [{ json: { post_id, plattform: 'linkedin', ok: true, url: null } }];

const alle = $input.all().map(i => i.json);
const gruppen = {};
for (const r of alle) {
  gruppen[r.post_id] = gruppen[r.post_id] || [];
  gruppen[r.post_id].push(r);
}
return Object.entries(gruppen).map(([post_id, ergebnisse]) => {
  const ergebnisObj = {};
  for (const e of ergebnisse) ergebnisObj[e.plattform] = { ok: e.ok, url: e.url || null, fehler: e.fehler || null };
  const alleOk = ergebnisse.every(e => e.ok);
  const keinErfolg = ergebnisse.every(e => !e.ok);
  const status = alleOk ? 'veroeffentlicht' : (keinErfolg ? 'fehler' : 'teilweise_veroeffentlicht');
  const fehlerText = ergebnisse.filter(e => !e.ok).map(e => e.plattform + ': ' + e.fehler).join(' | ');
  return { json: { post_id, status, ergebnis: ergebnisObj, fehler: fehlerText } };
});
